'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),c=require('./native-fixtures-20261003.cjs').environment().ctx,E=c.JYWestern,C=c.JYWesternCompletion,results=[];
function test(name,fn){fn();results.push({name,status:'passed'});console.log('PASS '+name);}
const input={utc:'1983-08-25T06:55:00Z',reference:'2026-10-03T04:00:00Z',latitude:23.31,longitude:120.31};
test('Regiomontanus5個南北半球／赤道／高纬算例60宫头與Swiss獨立星曆相符',()=>{const f=require('./fixtures/western-regiomontanus-swiss-20261003.json');for(const x of f.cases){const h=E.houses(x.utc,x.latitude,x.longitude,'R');for(let i=0;i<12;i++)assert(Math.abs(E.diff(h.cusps[i],x.cusps[i]))<.005,'cusp'+(i+1)+' '+h.cusps[i]+' '+x.cusps[i]);assert(Math.abs(E.diff(h.angles.ASC,x.angles.ASC))<.005);assert(Math.abs(E.diff(h.angles.MC,x.angles.MC))<.005);}});
test('迁居盤同一UTC十星黃經不變，實際重算四角十二宮和落宮',()=>{const b=E.compute(input),r=E.compute({...input,relocation:{latitude:51.507,longitude:-.127}});assert.equal(r.relocated.status,'calculated');assert.equal(r.relocated.houses.cusps.length,12);assert(Math.abs(E.diff(r.relocated.houses.angles.ASC,b.houses.angles.ASC))>10);for(const k of E.KEYS){assert.equal(r.relocated.planets[k].longitude,b.planets[k].longitude);assert.equal(r.relocated.planets[k].house,E.houseOf(b.planets[k].longitude,r.relocated.houses.cusps));}assert.throws(()=>E.compute({...input,relocation:{latitude:51}}));});
const h=E.compute({utc:'2026-10-03T04:00:00Z',reference:'2026-10-03T04:00:00Z',latitude:25.03,longitude:121.56,chartPurpose:'horary',houseSystem:'R',horaryHouse:10,horaryDays:7});
test('問事時刻卜卦盤實算12宮主與问事10宫，無借用本命次限回歸',()=>{assert.equal(h.input.chartPurpose,'horary');assert.equal(h.horary.significators.length,12);assert.equal(h.horary.quesited.house,10);assert.equal(h.progressions,null);assert.equal(h.activeSolarReturn,null);assert.equal(h.solarReturn,null);for(const s of h.horary.significators)assert.equal(s.lord,E.LORDS[Math.floor(h.houses.cusps[s.house-1]/30)]);});
test('行星光圈两版具名，取两星光圈之半而不借現代角度容許度',()=>{assert.equal(h.horary.orbPolicy.planetaryOrbs.Mars,7);assert.equal(h.horary.orbPolicy.planetaryOrbs.Jupiter,9);for(const a of h.horary.traditionalAspects)assert.equal(a.allowedOrb,(h.horary.orbPolicy.planetaryOrbs[a.a]+h.horary.orbPolicy.planetaryOrbs[a.b])/2);const wide=C.horary(h,{horaryDays:1,horaryOrbProfile:'HOULDING_WIDE'});assert.equal(wide.orbPolicy.planetaryOrbs.Mars,8);assert.throws(()=>C.horary(h,{horaryOrbProfile:'made-up'}));});
test('未来7日精確相位、換座與轉向來自星曆求根；每筆星位條件皆重新驗算',()=>{const t=h.horary.timeline;assert(t.events.length>5&&t.ingresses.length);for(const e of t.events){const a=E.position(e.a,e.utc),b=E.position(e.b,e.utc);assert(Math.abs(Math.abs(E.diff(a.longitude,b.longitude))-e.angle)<.0001);assert(Date.parse(e.utc)>Date.parse(t.start));}for(const e of t.ingresses)assert(Math.abs(E.diff(E.position(e.planet,e.utc).longitude,e.boundary))<.0001);assert(h.horary.moon.nextIngress);});
test('古典入相與換座前精確相位空亡分開，傳光集光及阻止候選不冒充實際結局',()=>{const v=h.horary;assert.equal(v.moon.voidExactBeforeIngress,v.moon.exactBeforeIngress.length===0);for(const t of [...v.translationCandidates,...v.collectionCandidates])assert.equal(t.status,'structural-candidate');for(const d of v.perfectionAndInterference)if(d.perfection)assert(d.interveningAspects.every(e=>Date.parse(e.utc)<Date.parse(d.perfection.utc)));});
test('新增卜卦與迁居全部事實傳入原生JSON和提示詞',()=>{const n=c.JYNativeAnalysis.analyze('astro',h),p=c.JYWesternPrompt.build(h,{question:'問工作'});assert(n.horary&&n.horary.timeline);assert(p.includes('orbPolicy')&&p.includes(h.horary.timeline.events[0].utc));assert(!/NaN|undefined|\[object Object\]/.test(p));});
test('午後問事／事件盤接受同日中午觀察日，不計算負齡本命運限；本命仍拒絕觀察日早於出生',()=>{
 const x={utc:'2026-10-03T06:55:00Z',reference:'2026-10-03T04:00:00Z',latitude:25.03,longitude:121.56,horaryDays:1};for(const chartPurpose of ['horary','event']){const r=E.compute({...x,chartPurpose});assert.equal(r.progressions,null);assert.equal(r.solarReturn,null);assert.equal(r.activeSolarReturn,null);assert.equal(r.input.reference,x.reference.replace('Z','.000Z'));}assert.throws(()=>E.compute({...x,chartPurpose:'natal'}),/早於/);
});
fs.writeFileSync(path.join(__dirname,'../docs/western-completion-validation-20261003.json'),JSON.stringify({testedAt:new Date().toISOString(),passed:results.length,failed:0,regiomontanusIndependentCusps:60,results},null,2));
fs.writeFileSync(path.join(__dirname,'../tests/fixtures/western-horary-generated-20261003.json'),JSON.stringify(h.horary.timeline,null,2));
